command:
// ==========================================
// LUNAS WIRKUNG: LANGE TASTHAARE (ZERZAL)
//
// - Ziel: sich selbst
// - Dunkelsicht: 8 Schritt
// - Erschütterungssinn: 4 Schritt
// - Unsichtbares spüren: 4 Schritt
// - Dauer: QS × 3 Minuten
// - Effektanlage über Block 6
// - Wirkungsende über Block 7
// - öffentliche Gabenkarte über Block 11
// - keine automatische Sichtänderung
// - GM stellt Entdeckungsmodi manuell ein
// ==========================================

(async function () {

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt =
    !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
    !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
    !globalThis.DSK?.GabenUI?.AnfrageKartenInhalt;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;

if (!DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
    !DSK_FW?.GabenUI?.AnfrageKartenInhalt
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Lange Tasthaare", vollerName = "Lange Tasthaare (Zerzal)", ahne = "Zerzal";
const endeKey = "zerzalTasthaare";
const dunkelsichtReichweite = 8, sonderSichtReichweite = 4;

const endeText =
    `Die übernatürliche Wahrnehmung der Tasthaare verblasst wieder.` +
    `<br><br><b style="color:#B30000;">Bitte an den GM:</b> Stelle die Entdeckungsmodi des Tokens wieder auf die vorherigen Werte zurück.`;

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
};

const findeEffekte = (actor, casterUuid) => (actor?.effects || []).filter(effect =>
    (effect.name || effect.label || "") === vollerName &&
    effect.getFlag("dsk", "isLangeTasthaare") === true &&
    effect.getFlag("dsk", "casterUuid") === casterUuid
);

// +++ 4 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables.map(token => token.actor)
            .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
        game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) || null;
}

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
if (!game.user.isGM && !casterActor.isOwner) {
    return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
}

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Kein Token des Wirkenden gefunden!");

const casterName = DSK_FW.ResolveTokenName(casterActor);

const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor, gabenName,
    suchbegriffe: ["Lange Tasthaare Probe", "Lange Tasthaare"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0, protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: "Die übernatürliche Wahrnehmung der Tasthaare konnte nicht aktiviert werden.",
        wirkender: casterName, ziele: [], misserfolge: [{ name: casterName }],
        dauerText: "0 Minuten",
        gmBereich: false, angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 5 - WERTE UND BESCHREIBUNG ++++++++++++++++++++++++++++++

const dauerMinuten = qs * 3;
const dauerText = `${dauerMinuten} Minuten (${qs} QS × 3 Min.)`;

const basisBeschreibung =
    `<b>${casterName}</b> sträubt die Tasthaare und nimmt feinste Strömungen wahr.` +
    `<br><br>Das Zerzalkind kann seine Umgebung tastend wahrnehmen, ohne sie zu berühren, und sich auch in völliger Dunkelheit orientieren.` +
    `<br><br><b>Entdeckungsmodi:</b>` +
    `<br>• Dunkelsicht: <b>${dunkelsichtReichweite} Schritt</b>` +
    `<br>• Erschütterungssinn: <b>${sonderSichtReichweite} Schritt</b>` +
    `<br>• Unsichtbares spüren: <b>${sonderSichtReichweite} Schritt</b>`;

// +++ 6 - ALTEN EIGENEN EFFEKT ERSETZEN +++++++++++++++++++++++

const alteEffekte = findeEffekte(casterActor, casterActor.uuid);

if (alteEffekte.length) {
    await casterActor.deleteEmbeddedDocuments(
        "ActiveEffect",
        alteEffekte.map(effect => effect.id)
    );
}

// +++ 7 - EFFEKT ÜBER BLOCK 6 ++++++++++++++++++++++++++++++++

const effekt = await DSK_FW.Effekt.Anwenden({
    name: vollerName, ahne,
    beschreibung:
        basisBeschreibung +
        `<br><br><b style="color:#B30000;">Bitte an den GM:</b> Stelle für die Dauer des Effekts beim Token folgende Entdeckungsmodi ein:` +
        `<br>• Dunkelsicht: <b>${dunkelsichtReichweite} Schritt</b>` +
        `<br>• Erschütterungssinn: <b>${sonderSichtReichweite} Schritt</b>` +
        `<br>• Unsichtbares spüren: <b>${sonderSichtReichweite} Schritt</b>` +
        `<br><br><b>Wirkungsdauer:</b> ${dauerText}`,
    gabeZiel: "",
    qs,
    ziel: casterActor,
    duration: {
        seconds: dauerMinuten * 60,
        startTime: game.time.worldTime
    },
    showIcon: 1,
    flags: { dsk: {
        isLangeTasthaare: true,
        casterUuid: casterActor.uuid,
        qs,
        dunkelsichtReichweite,
        sonderSichtReichweite,
        wirkungsende: {
            sfName: endeKey,
            basisEffektName: vollerName,
            beschreibungFuerEnde: endeText
        }
    }}
});

if (!effekt) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Der Effekt Lange Tasthaare konnte nicht angelegt werden!");
}

// +++ 8 - EFFEKT KONTROLLIEREN ++++++++++++++++++++++++++++++++

const endeDaten = effekt.getFlag("dsk", "wirkungsende");

const erfolgreich =
    (effekt.name || effekt.label || "") === vollerName &&
    effekt.getFlag("dsk", "isLangeTasthaare") === true &&
    effekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
    Number(effekt.getFlag("dsk", "qs")) === qs &&
    Number(effekt.getFlag("dsk", "dunkelsichtReichweite")) === dunkelsichtReichweite &&
    Number(effekt.getFlag("dsk", "sonderSichtReichweite")) === sonderSichtReichweite &&
    endeDaten?.sfName === endeKey &&
    endeDaten?.basisEffektName === vollerName &&
    endeDaten?.beschreibungFuerEnde === endeText;

if (!erfolgreich) {
    await effekt.delete();
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Lange Tasthaare wurde nicht vollständig angelegt!");
}

// +++ 9 - ÖFFENTLICHE GABENKARTE + GM-HINWEIS ++++++++++++++++

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne,
    beschreibung: basisBeschreibung,
    wirkender: casterName,
    ziele: [], misserfolge: [],
    dauerText,
    gmBereich: false,
    angewendet: true,
    erfolgreich: true,
    anfragenderUserId: game.user.id
});

if (nachricht) {
    const html = DSK_FW.GabenUI.AnfrageKartenInhalt({
        gabenName: vollerName, ahne,
        beschreibung: basisBeschreibung,
        wirkender: casterName,
        ziele: [], misserfolge: [],
        dauerText,
        gmBereich: false,
        angewendet: true,
        erfolgreich: true
    });

    const temp = document.createElement("div");
    temp.innerHTML = html;

    const wirkenderListe = temp.querySelectorAll(".dsklist")[0];

    if (wirkenderListe) {
        wirkenderListe.insertAdjacentHTML(
            "afterend",
            `<p style="margin:8px 0 0;text-align:left;">` +
            `<b style="color:#B30000;">Bitte an den GM:</b> ` +
            `Stelle beim Token für die Dauer des Effekts ` +
            `<i>Dunkelsicht</i> auf <b>${dunkelsichtReichweite} Schritt</b>, ` +
            `<i>Erschütterungssinn</i> auf <b>${sonderSichtReichweite} Schritt</b> und ` +
            `<i>Unsichtbares spüren</i> auf <b>${sonderSichtReichweite} Schritt</b>.` +
            `</p>`
        );
    }

    await nachricht.update({ content: temp.innerHTML });
}

// +++ 10 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++++++

await raeumeQSAuf(casterActor);

}).call(this);
